CREATE TABLE device_categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO device_categories(id,name) VALUES
('router','Router'),('switch','Switch'),('access-point','Access Point'),('server','Servidor'),('desktop','Desktop'),('notebook','Notebook'),('printer','Impressora'),('ip-camera','Câmera IP'),('dvr','DVR'),('nvr','NVR'),('onu','ONU'),('ont','ONT'),('olt','OLT'),('modem','Modem'),('gateway','Gateway'),('firewall','Firewall'),('nas','NAS'),('storage','Storage'),('iot','IoT'),('ip-phone','Telefone IP'),('ata','ATA'),('antenna','Antena'),('radio','Rádio'),('ups','UPS / Nobreak'),('patch-panel','Patch Panel'),('other','Outro');
CREATE TABLE devices (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL CHECK(length(trim(name))>0), description TEXT NOT NULL DEFAULT '', category_id TEXT NOT NULL REFERENCES device_categories(id), manufacturer TEXT NOT NULL DEFAULT '', model TEXT NOT NULL DEFAULT '', serial_number TEXT NOT NULL DEFAULT '', hostname TEXT NOT NULL DEFAULT '', vlan TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', room TEXT NOT NULL DEFAULT '', rack TEXT NOT NULL DEFAULT '', rack_position TEXT NOT NULL DEFAULT '', operating_system TEXT NOT NULL DEFAULT '', firmware TEXT NOT NULL DEFAULT '', admin_url TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'unknown' CHECK(status IN ('online','offline','unknown','new','changed')), notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE device_addresses (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('ipv4','ipv6','mac')), address TEXT NOT NULL, interface TEXT NOT NULL DEFAULT '', vlan TEXT NOT NULL DEFAULT '', is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(device_id,type,address));
CREATE INDEX idx_devices_project ON devices(project_id); CREATE INDEX idx_devices_category ON devices(category_id); CREATE INDEX idx_devices_hostname ON devices(hostname); CREATE INDEX idx_addresses_device ON device_addresses(device_id); CREATE INDEX idx_addresses_address ON device_addresses(address);
